import assert from "node:assert/strict"
import fs from "node:fs/promises"
import { gzipSync } from "node:zlib"
import { chromium } from "@playwright/test"
const manifest=JSON.parse(await fs.readFile(".next/react-loadable-manifest.json","utf8")),entry=Object.entries(manifest).find(([key])=>key.includes("report-timing.tsx"));assert(entry&&entry[1].files.length,"report chart has its own lazy entry");const files=await Promise.all(entry[1].files.map(async file=>{const bytes=await fs.readFile(".next/"+file);return {file,bytes:bytes.length,gzipBytes:gzipSync(bytes).length}}));assert(files.reduce((n,f)=>n+f.gzipBytes,0)<250000,"report chart chunks stay below 250KB gzip");const browser=await chromium.launch({channel:"chrome",headless:true});let before=0,after=0;try{const page=await browser.newPage({viewport:{width:1536,height:1024}}),requests=[];await page.route("**/*",route=>route.request().headers()["next-router-prefetch"]?route.abort():route.continue());page.on("request",r=>{if(entry[1].files.some(file=>r.url().includes(file)))requests.push(r.url())});await page.goto("http://localhost:3031/preview/notifications");await page.locator(".pc-not-hydration:not([disabled])").waitFor();await page.getByRole("heading",{name:"Preparation report",exact:true}).waitFor();before=requests.length;assert.equal(before,0,"compact inbox does not fetch the report chart");await page.goto("http://localhost:3031/preview/notifications/reports/10000000-0000-4000-8000-000000000090");await page.getByRole("figure").first().waitFor();after=requests.length;assert(after>0,"full report loads chart on demand")}finally{await browser.close()}const result={recordedAt:new Date().toISOString(),chartRequestsBeforeFullReport:before,chartRequestsAfterFullReport:after,files};await fs.writeFile("docs/performance/notifications-bundle.json",JSON.stringify(result,null,2));console.log(JSON.stringify(result));
